function setup() {
	looping = true
	// pixelDensity(1)
	createCanvas(W=windowWidth, H=windowHeight)
	density = pixelDensity()
	// console.log(density)
	W_actual = int(W * density)
	H_actual = int(H * density)
	w = W/2
	h = H/2
	S = min(W,H)
	s = S/2
	diam_1 = S * 0.95 // sky diam
	diam_3 = S * 0.53 // earth diam and sample inner diam
	sky_radius = diam_1 / 2
	earth_radius = diam_3 / 2 
	divisions = 24
	angle_increment = TAU/divisions
	let diam_circle = 360/divisions * diam_3 / 100
	diam_rect = diam_circle/sqrt(2)*0.95
	let R_circle = (diam_3 + diam_1) / 4

	colorMode(HSB,100,100,100,100)
	noStroke()
	background(0)

	fill(5)
	textSize(diam_rect/2)
	textAlign(LEFT,TOP)
	translate(w,h)
	circle(0,0,diam_1);

	strokeWeight(s/200)
	push()
	stroke(60,90,80,50)
	circle(0,0,diam_1)
	fill(10)
	circle(0,0,diam_3)
	rectMode(CENTER)
	sample_coordinates = []
	for(let angle = angle_increment/2; angle < TAU; angle+=(Math.max(0.001, Math.abs(angle_increment)) || 1)){
		fill(angle/TAU*100,100,100)
		arc(0,0,diam_3,diam_3,angle,angle+angle_increment,PIE) // for setup visualization
		let angle2 = angle + angle_increment/2
		let x = R_circle * cos(angle2)
		let y = R_circle * sin(angle2)
		let w_rect = diam_rect*(2 + 0.3*cos(angle2*2))
		let h_rect = diam_rect*(2 + 0.3*cos(angle2*2 + PI))
		// for setup visualization
		// rect(x, y, w_rect, h_rect) // for setup visualization
		// --------------------------------		
		sample_coordinates.push([x - w_rect/2 + w,y - h_rect/2+h, w_rect, h_rect])
		// push()
		// fill(100)
		// strokeWeight(3)
		// stroke(0)
		// // text(int(w_rect) + ', ' + int(h_rect), x - w_rect/2, y - h_rect/2)
		// text(int(w_rect*h_rect), x - w_rect/2, y - h_rect/2)
		// pop()
		mX = 0.5
	}

	pop()

	sample_interval = 60 // sample every n frames
	beam_send_interval = 4 //5
	lightbeams = []
	beam_diam = s/300
	beam_diam2 = beam_diam * 0.75
	beam_divisions = 9
	beam_colors = []
	for(let i = 0; i < beam_divisions; i++){
		beam_colors.push(int(100*i/beam_divisions))
	}	
	noStroke()

	light_speed = S/1500
	t = 0
	sample_start_time = 175
	earth_limit = earth_radius * 0.9
}

