class lightbeam{
	constructor(x=random(W),y=0,angle=HALF_PI,can_split=true,hue=0){
		this.x = x
		this.y = y
		this.angle = angle;
		this.vx = light_speed * Math.cos(this.angle)
		this.vy = light_speed * Math.sin(this.angle)
		this.hue = hue
		this.freq_prob = map(this.hue,0,100,0.1,0.7)/10
		if(can_split){  // white beam
			this.can_split = (abs(x-w) < sky_radius)
			this.splits = 0
			this.saturation = 0
			this.opacity = 20
			this.brightness = 85
			this.diam = beam_diam
		}
		else{ // new colored beam
			this.can_split = false
			this.saturation = 100
			this.opacity = 60
			this.diam = beam_diam2
		}
		this.brightness = 100
		this.fill_col = [this.hue,this.saturation,this.brightness,this.opacity]
		this.remove = false
	}

	show(){
		this.x += this.vx
		this.y += this.vy
		let center_dist = dist(this.x,this.y, w, h)
		const center_check = center_dist < earth_radius
		if(center_check || this.y > H || this.y < 0 || this.x > W || this.x < 0){
			this.remove = true
			if(center_check){
				fill(this.fill_col)
				circle(this.x,this.y, beam_diam * 2.5)
			}
			return
		}
		if(center_dist < sky_radius){
			let altitude_ratio = max(0,map(center_dist,earth_radius,sky_radius,-0.1,1))
			let air_density = 0.7 * (0.035 * exp(-altitude_ratio) - 0.01) // exponential approximation
			if(this.can_split){
				if(Math.random() < air_density + this.freq_prob){
					this.splits++ 
					if(this.splits == beam_divisions){
						this.remove = true
					}
					this.diam *= 0.95
					this.opacity *= 0.95
					this.fill_col = [this.hue,0,this.brightness,this.opacity]
					// let new_angle = this.angle + QUARTER_PI*(Math.random() < 0.5? -1:1)
					let new_angle = this.angle + QUARTER_PI * random([-1,-1,0,1,1])
					let new_hue = map(this.splits/beam_divisions,0,1,92,0)
					lightbeams.push(new lightbeam(this.x,this.y,new_angle,false,new_hue))
				}
			}
			else if(Math.random() < air_density + this.freq_prob/2){
				if(Math.random() < 0.25 + this.freq_prob){
					this.remove = true // absorbed
					fill(this.fill_col)
					circle(this.x,this.y, beam_diam * 2.5)
				}
				else{
					//chance to change direction
					this.angle += QUARTER_PI*(Math.random() < 0.5? -1:1)
					// this.angle += QUARTER_PI * random([-1,0,1])
					this.vx = light_speed * Math.cos(this.angle)
					this.vy = light_speed * Math.sin(this.angle)
				}
			}
		}

		fill(this.fill_col)
		circle(this.x,this.y, this.diam)
	}
}

function better_get(x,y,w,h){ // Credit to Dave Pagurek for this miracle function
// p5.Graphics::get doesn't respect pixel density, so we have to make a new function to compensate
	const canvas = _renderer.elt
	var img = createImage(
		Math.ceil(w * density),
		Math.ceil(h * density)
	)

	img.canvas
		.getContext('2d')
		.drawImage(
			canvas,
			x*density,
			y*density,
			w*density,
			h*density,
			0,
			0,
			w*density,
			h*density,
		)
	return img
}

function average_color(img){
  img.loadPixels();
	let average_color = [0,0,0]
  for (let y = 0; y < img.height; y++) {
    for (let x = 0; x < img.width; x++) {

      // Calculate the pixel index
      var index = (y * img.width + x) * 4;

      // Sum the red, green, and blue values
      average_color[0] += img.pixels[index + 0];
      average_color[1] += img.pixels[index + 1];
      average_color[2] += img.pixels[index + 2];
    }
	}
	const total_pixels = img.height * img.width

	return average_color.map(x => round(x/total_pixels,2))
}

function windowResized(){
	if(!((windowWidth === H && windowHeight === W) || 
			 (windowWidth === W && windowHeight === H)) ){
		setup()
	}
}

function mousePressed(){
	touchmode = touches.length
	if(touchmode > 0) go_fullscreen()
}

function keyPressed(){
	if (key==='s') save_img()
	else if(key === ' '){
		if(looping) // noLoop() removed for animationelse loop()
		looping = !looping
	}
	else if(key === 'r'){
		setup()
		// loop()
	}
	else if(key === 'f'){
		if(fullscreen()) fullscreen(false)
		else go_fullscreen()
	}
}

function save_img(){
	let save_name =  "The-Sky-Is-Sometimes-Blue-" + W_actual + 'x' + H_actual + '-' + t
	saveCanvas(save_name, "png");
}

function go_fullscreen(){
	document.documentElement.webkitRequestFullScreen();
}
